. (Join-Path $PSScriptRoot 'experiment-1-22-artifact-contract.ps1')
$script:Exp124Required=@('run-config.json','client-results.json','client-progress.jsonl','pool/pool-metrics.jsonl','pool/pool-metrics.jsonl.summary.json','pool/collector-coverage.json','pool/collector-lifecycle.json','provenance/artifact-path-preflight.json','application/container-stop.json','application/docker-logs.stdout.log','application/docker-logs.stderr.log','application/docker-logs-capture.json','application/application.log','database/database-metrics.jsonl','container/container-stats.jsonl','mock/load-stop-mock-metrics.json','drain/mock-drain-summary.json','verification-summary.json','provenance/artifact-path-preflight.json','provenance/runtime-provenance.json','provenance/execution-timeline.json','execution-summary.json')
function Write-Exp124Json($Value,[string]$Path){New-Item -ItemType Directory -Force (Split-Path $Path)|Out-Null;$Value|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $Path -Encoding UTF8}
function Get-Exp124Json([string]$Path){Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json -ErrorAction Stop}
function Get-Exp124Time($Object,[string]$Name){$d=[DateTimeOffset]::MinValue;if(-not[DateTimeOffset]::TryParse([string]$Object.$Name,[ref]$d)){throw "Invalid timestamp: $Name"};$d.ToUniversalTime()}
function Assert-Exp124Timeline([object]$Timeline){$keys=@('artifactPathPreflightStartedAt','artifactPathPreflightCompletedAt','collectorProcessStartedAt','collectorFirstValidSampleAt','coreInvocationStartedAt','coreInvocationCompletedAt','collectorFirstSampleCoveringCoreEndAt','postCoreCoverageConfirmedAt','collectorStopSignalIssuedAt','collectorProcessCompletedAt','applicationStopStartedAt','applicationStopCompletedAt','applicationLogCaptureStartedAt','applicationLogCaptureCompletedAt','artifactValidationCompletedAt','finalizationCompletedAt');$v=@{};foreach($k in $keys){$v[$k]=Get-Exp124Time $Timeline $k};for($i=1;$i-lt$keys.Count;$i++){if($v[$keys[$i]]-lt$v[$keys[$i-1]]){throw "Timeline order invalid: $($keys[$i-1]) -> $($keys[$i])"}};if($Timeline.collectorFirstSampleCoveringCoreEndAt -ne $Timeline.coverageFirstSampleCoveringCoreEndAt -and $null -ne $Timeline.coverageFirstSampleCoveringCoreEndAt){throw 'Timeline coverage identity mismatch'}}
function Assert-Exp124CollectorLifecycle([string]$Root){$l=Get-Exp124Json (Join-Path $Root 'pool/collector-lifecycle.json');$tl=Get-Exp124Json (Join-Path $Root 'provenance/execution-timeline.json');foreach($k in @('summaryCollectorStatus','summaryFailures','summaryStopSignalObserved')){if($null -eq $l.PSObject.Properties[$k]){throw "Lifecycle field missing: $k"}};if($l.mode-ne'CORE_BOUND_STOP_SIGNAL'-or$l.lifecycleStatus-ne'COLLECTOR_LIFECYCLE_PASSED'-or$l.failureType-ne$null-or$l.stopSignalObserved-ne$true-or$l.processExitCode-ne0-or$l.summaryCollectorStatus-ne'COLLECTOR_STOPPED_BY_SIGNAL'-or$l.summaryFailures-ne0-or$l.summaryStopSignalObserved-ne$true){throw 'Collector lifecycle contract failed'};foreach($k in @('collectorFirstSampleCoveringCoreEndAt','postCoreCoverageConfirmedAt','collectorStopSignalIssuedAt','collectorProcessCompletedAt')){if($l.$k -ne $tl.$k){throw "Lifecycle timeline identity mismatch: $k"}}}
function Assert-Exp124CollectorCoverage([string]$Root){$c=Get-Exp124Json (Join-Path $Root 'pool/collector-coverage.json');$l=Get-Exp124Json (Join-Path $Root 'pool/collector-lifecycle.json');$tl=Get-Exp124Json (Join-Path $Root 'provenance/execution-timeline.json');if($c.coverageStatus-ne'COLLECTOR_COVERAGE_PASSED'-or-not$c.coversCoreStart-or-not$c.coversCoreEnd-or$c.invalidSampleCount-ne0-or$c.collectorFailures-ne0){throw 'Collector coverage contract failed'};if($c.collectorFirstSampleCoveringCoreEndAt -ne $c.waitReturnedFirstCoveringSampleAt-or$c.collectorFirstSampleCoveringCoreEndAt -ne $l.collectorFirstSampleCoveringCoreEndAt-or$c.collectorFirstSampleCoveringCoreEndAt -ne $tl.collectorFirstSampleCoveringCoreEndAt){throw 'Coverage first-covering identity failed'};if((Get-Exp124Time $c 'collectorFirstSampleCoveringCoreEndAt') -lt (Get-Exp124Time $c 'coreInvocationCompletedAt')){throw 'First-covering sample precedes core end'}}
function Assert-Exp124RuntimeProvenance([string]$Root){$p=Get-Exp124Json (Join-Path $Root 'provenance/runtime-provenance.json');$r=Get-Exp124Json (Join-Path $Root 'run-config.json');$tl=Get-Exp124Json (Join-Path $Root 'provenance/execution-timeline.json');if($p.runtimeProvenance-ne'ACTUAL'-or$p.runId-ne$r.runId-or$p.runDate-ne$r.runDate-or$p.condition-ne$r.condition-or$p.applicationImageTag-ne$r.applicationImageTag-or$p.applicationImageId-ne$r.applicationImageId-or$p.mockImageTag-ne$r.mockImageTag-or$p.mockImageId-ne$r.mockImageId-or$p.collectorMode-ne'CORE_BOUND_STOP_SIGNAL'){throw 'Runtime provenance mismatch'};foreach($k in @('leasingStrategy','maxIdleTimeMs','evictionIntervalMs')){if($p.policy.$k -ne $r.policy.$k){throw "Runtime policy mismatch: $k"}};if([string]::IsNullOrWhiteSpace([string]$p.collectorReadyAt)-or[DateTimeOffset]::Parse($p.collectorReadyAt) -lt [DateTimeOffset]::Parse($p.collectorFirstValidSampleAt)-or$p.collectorFirstValidSampleAt -ne $tl.collectorFirstValidSampleAt){throw 'Collector provenance timestamp mismatch'};if($p.composeFiles.Count-ne7-or$r.composeFiles.Count-ne7){throw 'Compose provenance incomplete'};foreach($f in $p.composeFiles){$match=@($r.composeFiles|Where-Object{[string]$_.path -eq [string]$f.path});if($match.Count-ne1){throw "Compose path mismatch: $($f.path)"};if($match[0].sha256 -ne $f.sha256){throw "Compose provenance hash mismatch: $($f.path)"};$actual=(Get-FileHash -LiteralPath (Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path $f.path) -Algorithm SHA256).Hash.ToLowerInvariant();if($f.sha256 -ne$actual){throw "Compose SHA-256 mismatch: $($f.path)"}}}
function Assert-Exp124StopIdentity([string]$Root){$r=Get-Exp124Json (Join-Path $Root 'run-config.json');$s=Get-Exp124Json (Join-Path $Root 'application/container-stop.json');$tl=Get-Exp124Json (Join-Path $Root 'provenance/execution-timeline.json');if($s.runId-ne$r.runId-or[string]::IsNullOrWhiteSpace($s.containerId)-or[string]::IsNullOrWhiteSpace($s.command)-or$s.gracePeriodSeconds-ne15-or$s.processTimeoutSeconds-ne30-or$s.timedOut-ne$false-or$s.exitCode-ne0-or$s.stateBefore-ne'running'-or@('exited','stopped')-notcontains$s.stateAfter-or$s.containerStillExists-ne$true-or$s.inspectExitCodeBefore-ne0-or$s.inspectExitCodeAfter-ne0-or$s.stopStatus-ne'APPLICATION_CONTAINER_STOPPED'){throw 'Stop contract failed'};if((Get-Exp124Time $s 'completedAt')-lt(Get-Exp124Time $s 'startedAt')){throw 'Stop timestamp order failed'};if($tl.applicationStopStartedAt -cne $s.startedAt -or$tl.applicationStopCompletedAt -cne $s.completedAt){throw 'Stop timeline identity failed'}}
function Assert-Exp124CaptureIdentity([string]$Root){$r=Get-Exp124Json (Join-Path $Root 'run-config.json');$s=Get-Exp124Json (Join-Path $Root 'application/container-stop.json');$c=Get-Exp124Json (Join-Path $Root 'application/docker-logs-capture.json');$tl=Get-Exp124Json (Join-Path $Root 'provenance/execution-timeline.json');if($s.runId-ne$r.runId-or$c.runId-ne$r.runId-or$s.containerId-ne$c.containerId-or$c.captureMode-ne'POST_STOP_SNAPSHOT'-or@('exited','stopped')-notcontains$c.containerStateAtCapture-or$c.timeoutSeconds-ne30-or$c.timedOut-ne$false-or$c.exitCode-ne0-or$c.captureStatus-ne'APPLICATION_LOG_CAPTURE_PASSED'){throw 'Capture contract failed'};$appRoot=[IO.Path]::GetFullPath((Join-Path $Root 'application')).TrimEnd('\','/')+'\';foreach($p in @($c.stdoutPath,$c.stderrPath,$c.combinedPath)){if(-not(Test-Path $p)){throw 'Capture path missing'};$candidate=[IO.Path]::GetFullPath($p);$relative=[IO.Path]::GetRelativePath($appRoot,$candidate);if([IO.Path]::IsPathRooted($relative)-or$relative -eq '..'-or$relative.StartsWith('..\')-or$relative.StartsWith('../')){throw 'Capture path containment failed'}};if([IO.Path]::GetFullPath($c.stdoutPath) -cne (Join-Path $appRoot 'docker-logs.stdout.log')-or[IO.Path]::GetFullPath($c.stderrPath) -cne (Join-Path $appRoot 'docker-logs.stderr.log')-or[IO.Path]::GetFullPath($c.combinedPath) -cne (Join-Path $appRoot 'application.log')){throw 'Capture filename identity failed'};if([int64]$c.stdoutBytes-ne([IO.FileInfo]::new($c.stdoutPath)).Length-or[int64]$c.stderrBytes-ne([IO.FileInfo]::new($c.stderrPath)).Length-or[int64]$c.combinedBytes-ne([IO.FileInfo]::new($c.combinedPath)).Length-or([int64]$c.stdoutBytes+[int64]$c.stderrBytes)-le0-or[int64]$c.combinedBytes-le0){throw 'Capture byte contract failed'};if($tl.applicationLogCaptureStartedAt -cne $c.startedAt -or$tl.applicationLogCaptureCompletedAt -cne $c.completedAt){throw 'Capture timeline identity failed'}}
function Assert-Exp124BaseArtifacts([string]$Root){foreach($r in $script:Exp124Required){$p=Join-Path $Root $r;if(-not(Test-Path $p)){throw "Required artifact missing: $r"};if($r -notin @('application/docker-logs.stdout.log','application/docker-logs.stderr.log') -and([IO.FileInfo]::new($p)).Length-le0){throw "Required artifact empty: $r"}};foreach($r in @('run-config.json','pool/pool-metrics.jsonl.summary.json','pool/collector-coverage.json','pool/collector-lifecycle.json','application/container-stop.json','application/docker-logs-capture.json','provenance/runtime-provenance.json','provenance/execution-timeline.json','execution-summary.json')){$null=Get-Exp124Json (Join-Path $Root $r)};$lines=@(Get-Content (Join-Path $Root 'pool/pool-metrics.jsonl')|Where-Object{$_.Trim()});if($lines.Count-le1){throw 'Pool samples incomplete'};foreach($line in $lines){$null=$line|ConvertFrom-Json};Assert-Exp124CollectorLifecycle $Root;Assert-Exp124CollectorCoverage $Root;Assert-Exp124ArtifactPathPreflight $Root;Assert-Exp124RuntimeProvenance $Root;Assert-Exp124CaptureIdentity $Root}
function Assert-Exp124StructuralArtifacts([string]$Root){Assert-Exp124StopIdentity $Root;Assert-Exp124BaseArtifacts $Root;$s=Get-Exp124Json (Join-Path $Root 'execution-summary.json');if($s.executionStatus-ne'FINALIZING'-or$s.artifactValidation-ne'PENDING'){throw 'Structural summary invalid'}}
function Assert-Exp124CommittedArtifacts([string]$Root){Assert-Exp124StopIdentity $Root;Assert-Exp124BaseArtifacts $Root;$s=Get-Exp124Json (Join-Path $Root 'execution-summary.json');if($s.executionStatus-ne'COMPLETED'-or$s.artifactValidation-ne'PASSED'){throw 'Committed summary invalid'};$tl=Get-Exp124Json (Join-Path $Root 'provenance/execution-timeline.json');Assert-Exp124Timeline $tl}
function Set-Exp124Terminal([string]$Root,[ValidateSet('COMPLETED','EXECUTION_FAILED')][string]$State){Remove-Item (Join-Path $Root 'RUNNING') -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path $Root 'COMPLETED') -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path $Root 'EXECUTION_FAILED') -Force -ErrorAction SilentlyContinue;New-Item -ItemType File (Join-Path $Root $State)|Out-Null}










